+/// Dedicated DeepSeek V4.1 renderer.
+#[derive(Debug, Clone, Copy, Default)]
+pub struct DeepSeekV41ChatRenderer;
+
+impl DeepSeekV41ChatRenderer {
+    pub fn new() -> Self {
+        Self
+    }
